decade_totals = [decade_breakdown[d]['total'] for d in decades]
decade_uniques = [decade_breakdown[d]['unique'] for d in decades]
decade_repeats = [decade_breakdown[d]['total'] - decade_breakdown[d]['unique'] for d in decades]

# Top 10 composers for bar chart
top10 = composer_counts[:10]
top10_names = [c[0] for c in top10]
top10_counts = [c[1] for c in top10]

# Era data
era_names = list(era_breakdown.keys())
era_totals = [era_breakdown[e]['total'] for e in era_names]
era_uniques = [era_breakdown[e]['unique'] for e in era_names]

# Composer timeline data: years vs composers
timeline_data = {}
for r in rows:
    c = r['Composer']
    y = r['Year']
    if c not in timeline_data:
        timeline_data[c] = []
    timeline_data[c].append(y)

